final_template:
AWSTemplateFormatVersion: "2010-09-09"
Description: "IoT Core Policy for Device Onboarding using Lambda-backed Custom Resource"

Parameters:
  ThingName:
    Type: String
    Description: "The IoT thing name to scope the policy for device onboarding"
    Default: "DeviceOnboardingThing"

Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: IoTDevicePolicyLambdaPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: "arn:aws:logs:*:*:*"
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                  - iot:ListPolicyVersions
                  - iot:DeletePolicyVersion
                  - iot:CreatePolicyVersion
                  - iot:SetDefaultPolicyVersion
                  - iot:ListTargetsForPolicy
                  - iot:DetachPolicy
                Resource: "*"

  IoTDevicePolicyFunction:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Role: !GetAtt LambdaExecutionRole.Arn
      Runtime: nodejs24.x
      Timeout: 300
      MemorySize: 256
      Code:
        ZipFile: |
          const https = require('https');
          const AWS = require('aws-sdk');
          const iot = new AWS.Iot({ region: process.env.AWS_REGION });

          exports.handler = async (event, context) => {
            console.log('Received event:', JSON.stringify(event, null, 2));
            const thingName = event.ResourceProperties.ThingName;
            const stackId = event.StackId;
            const uniqueSuffix = stackId.split('/')[2]; // Use stack ID for uniqueness
            const policyName = `DeviceOnboardingPolicy-${thingName}-${uniqueSuffix}`;
            const region = process.env.AWS_REGION;
            const accountId = context.invokedFunctionArn.split(':')[4];
            const physicalResourceId = policyName;
            const responseURL = event.ResponseURL;

            const policyDocument = {
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: "iot:Connect",
                  Resource: `arn:aws:iot:${region}:${accountId}:client/${thingName}`
                },
                {
                  Effect: "Allow",
                  Action: "iot:Publish",
                  Resource: `arn:aws:iot:${region}:${accountId}:topic/${thingName}/*`
                },
                {
                  Effect: "Allow",
                  Action: "iot:Subscribe",
                  Resource: `arn:aws:iot:${region}:${accountId}:topicfilter/${thingName}/*`
                },
                {
                  Effect: "Allow",
                  Action: "iot:Receive",
                  Resource: `arn:aws:iot:${region}:${accountId}:topic/${thingName}/*`
                }
              ]
            };

            let responseStatus = "SUCCESS";
            let responseData = {};

            try {
              if (event.RequestType === "Create") {
                console.log('Creating policy:', policyName);
                await iot.createPolicy({
                  policyName,
                  policyDocument: JSON.stringify(policyDocument)
                }).promise();
                responseData = { PolicyName: policyName };
                console.log('Policy created successfully');
              } else if (event.RequestType === "Update") {
                console.log('Updating policy:', policyName);
                await iot.createPolicyVersion({
                  policyName,
                  policyDocument: JSON.stringify(policyDocument),
                  setAsDefault: true
                }).promise();
                const versions = await iot.listPolicyVersions({ policyName }).promise();
                for (const version of versions.policyVersions) {
                  if (!version.isDefaultVersion) {
                    await iot.deletePolicyVersion({ policyName, policyVersionId: version.versionId }).promise();
                  }
                }
                responseData = { PolicyName: policyName };
                console.log('Policy updated successfully');
              } else if (event.RequestType === "Delete") {
                console.log('Deleting policy:', policyName);
                try {
                  const targets = await iot.listTargetsForPolicy({ policyName }).promise();
                  for (const target of targets.targets) {
                    await iot.detachPolicy({ policyName, target }).promise();
                  }
                } catch (err) {
                  if (err.code !== 'ResourceNotFoundException') throw err;
                }
                try {
                  const versions = await iot.listPolicyVersions({ policyName }).promise();
                  for (const version of versions.policyVersions) {
                    if (!version.isDefaultVersion) {
                      await iot.deletePolicyVersion({ policyName, policyVersionId: version.versionId }).promise();
                    }
                  }
                  await iot.deletePolicy({ policyName }).promise();
                } catch (err) {
                  if (err.code !== 'ResourceNotFoundException') throw err;
                }
                console.log('Policy deleted successfully');
              }
            } catch (err) {
              console.error('Error processing custom resource:', err);
              responseStatus = "FAILED";
              responseData = { Error: err.message };
            }

            // Send response to CloudFormation
            const responseBody = JSON.stringify({
              Status: responseStatus,
              Reason: responseData.Error || 'See CloudWatch Logs',
              PhysicalResourceId: physicalResourceId,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              Data: responseData
            });

            const url = new URL(responseURL);
            const options = {
              hostname: url.hostname,
              path: url.pathname + url.search,
              method: 'PUT',
              headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(responseBody)
              }
            };

            return new Promise((resolve, reject) => {
              const req = https.request(options, (res) => {
                console.log('Response status:', res.statusCode);
                resolve();
              });
              req.on('error', (err) => {
                console.error('Error sending response:', err);
                reject(err);
              });
              req.write(responseBody);
              req.end();
            });
          };

  IoTDevicePolicyCustomResource:
    Type: Custom::IoTDevicePolicy
    Properties:
      ServiceToken: !GetAtt IoTDevicePolicyFunction.Arn
      ThingName: !Ref ThingName

Outputs:
  PolicyName:
    Description: "The name of the IoT Core policy created for device onboarding"
    Value: !GetAtt IoTDevicePolicyCustomResource.PolicyName

AWSTemplateFormatVersion: "2010-09-09"
Description: "CloudFormation template for Step Functions calculator demo with Lambda and state machine."
Resources:
  CalculatorLambdaRole:
    Type: "AWS::IAM::Role"
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: "sts:AssumeRole"
      ManagedPolicyArns:
        - "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"

  CalculatorLogGroup:
    Type: "AWS::Logs::LogGroup"
    Properties:
      LogGroupName: "/aws/lambda/Calculator"
      RetentionInDays: 3

  CalculatorLambda:
    Type: "AWS::Lambda::Function"
    DependsOn:
      - CalculatorLogGroup
    Properties:
      FunctionName: "Calculator"
      Runtime: "nodejs24.x"
      Handler: "index.handler"
      Role: !GetAtt CalculatorLambdaRole.Arn
      Timeout: 30
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const { operator, operands } = event;
            if (!operator || !operands || operands.length !== 2) {
              throw new Error('Invalid input. Expected {"operator": "add", "operands": [a,b]}');
            }
            const [a, b] = operands;
            let result;
            switch (operator) {
              case 'add':
                result = a + b;
                break;
              case 'subtract':
                result = a - b;
                break;
              case 'multiply':
                result = a * b;
                break;
              case 'divide':
                if (b === 0) {
                  throw new Error('Division by zero');
                }
                result = a / b;
                break;
              default:
                throw new Error(`Unsupported operator: ${operator}`);
            }
            return { result };
          };

  CalculatorStateMachineRole:
    Type: "AWS::IAM::Role"
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: "sts:AssumeRole"
      Policies:
        - PolicyName: "InvokeCalculatorLambda"
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action: "lambda:InvokeFunction"
                Resource: !GetAtt CalculatorLambda.Arn

  CalculatorStateMachine:
    Type: "AWS::StepFunctions::StateMachine"
    Properties:
      StateMachineName: "Calculator-StateMachine"
      RoleArn: !GetAtt CalculatorStateMachineRole.Arn
      DefinitionString:
        Fn::Sub:
          - |
            {
              "Comment": "Calculator state machine",
              "StartAt": "CheckOperator",
              "States": {
                "CheckOperator": {
                  "Type": "Choice",
                  "Choices": [
                    {"Variable": "$.operator", "StringEquals": "add", "Next": "Calculate"},
                    {"Variable": "$.operator", "StringEquals": "subtract", "Next": "Calculate"},
                    {"Variable": "$.operator", "StringEquals": "multiply", "Next": "Calculate"},
                    {"Variable": "$.operator", "StringEquals": "divide", "Next": "Calculate"}
                  ],
                  "Default": "UnknownOperator"
                },
                "Calculate": {
                  "Type": "Task",
                  "Resource": "arn:aws:states:::lambda:invoke",
                  "Parameters": {
                    "FunctionName": "${LambdaArn}",
                    "Payload.$": "$"
                  },
                  "ResultPath": "$.result",
                  "End": true
                },
                "UnknownOperator": {
                  "Type": "Fail",
                  "Cause": "Unknown operator",
                  "Error": "UnsupportedOperator"
                }
              }
            }
          - {LambdaArn: !GetAtt CalculatorLambda.Arn}

Outputs:
  StateMachineArn:
    Description: "ARN of the Calculator state machine"
    Value: !Ref CalculatorStateMachine
  SampleInput:
    Description: "Sample input format for the state machine"
    Value: '{"operator": "add", "operands": [1,2]}'

AWSTemplateFormatVersion: "2010-09-09"
Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      BillingMode: PAY_PER_REQUEST
  AppSyncRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/*"
  SimpleTodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
  AppSyncApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
  AppSyncSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          owner: String!
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }
        input CreateTodoInput {
          title: String!
          description: String
          owner: String!
        }
        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          owner: String
        }
        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }
        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }
        type TodoConnection {
          items: [Todo]
          nextToken: String
        }
        schema {
          query: Query
          mutation: Mutation
        }
  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      Name: TodoDataSource
      Type: AMAZON_DYNAMODB
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region
      ServiceRoleArn: !GetAtt AppSyncRole.Arn
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - AppSyncSchema
      - TodoDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: TodoDataSource
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        export function request(ctx) {
            const input = ctx.args.input;
            const id = util.autoId();
            const now = util.time.nowISO8601();
            const item = {
                id,
                title: input.title,
                description: input.description,
                owner: input.owner,
                createdAt: now,
                updatedAt: now,
            };
            return {
                operation: "PutItem",
                key: util.dynamodb.toMapValues({ id }),
                attributeValues: util.dynamodb.toMapValues(item),
            };
        }
        export function response(ctx) {
            if (ctx.error) {
                util.error(ctx.error.message, ctx.error.type);
            }
            return ctx.result;
        }
  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - AppSyncSchema
      - TodoDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: TodoDataSource
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        export function request(ctx) {
            const input = ctx.args.input;
            const now = util.time.nowISO8601();
            // Build update expression dynamically for provided fields
            let expression = "SET";
            const expressionNames = {};
            const expressionValues = {};
            const fields = ['title', 'description', 'owner'];
            for (const field of fields) {
                if (input[field] !== undefined) {
                    expression += ` #${field} = :${field},`;
                    expressionNames[`#${field}`] = field;
                    expressionValues[`:${field}`] = input[field];
                }
            }
            // Always set updatedAt
            expression += " #updatedAt = :updatedAt";
            expressionNames["#updatedAt"] = "updatedAt";
            expressionValues[":updatedAt"] = now;
            return {
                operation: "UpdateItem",
                key: util.dynamodb.toMapValues({ id: input.id }),
                update: {
                    expression: expression,
                    expressionNames: expressionNames,
                    expressionValues: util.dynamodb.toMapValues(expressionValues),
                },
            };
        }
        export function response(ctx) {
            if (ctx.error) {
                util.error(ctx.error.message, ctx.error.type);
            }
            return ctx.result;
        }
  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - AppSyncSchema
      - TodoDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: TodoDataSource
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        export function request(ctx) {
            const id = ctx.args.id;
            return {
                operation: "DeleteItem",
                key: util.dynamodb.toMapValues({ id }),
            };
        }
        export function response(ctx) {
            if (ctx.error) {
                util.error(ctx.error.message, ctx.error.type);
            }
            return ctx.result;
        }
  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - AppSyncSchema
      - TodoDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: TodoDataSource
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        export function request(ctx) {
            const id = ctx.args.id;
            return {
                operation: "GetItem",
                key: util.dynamodb.toMapValues({ id }),
            };
        }
        export function response(ctx) {
            if (ctx.error) {
                util.error(ctx.error.message, ctx.error.type);
            }
            return ctx.result;
        }
  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - AppSyncSchema
      - TodoDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: TodoDataSource
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        export function request(ctx) {
            const { limit, nextToken } = ctx.args;
            const request = { operation: "Scan" };
            if (limit !== undefined) request.limit = limit;
            if (nextToken !== undefined) request.nextToken = nextToken;
            return request;
        }
        export function response(ctx) {
            if (ctx.error) {
                util.error(ctx.error.message, ctx.error.type);
            }
            return {
                items: ctx.result.items,
                nextToken: ctx.result.nextToken,
            };
        }
  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn:
      - AppSyncSchema
      - TodoDataSource
    Properties:
      ApiId: !GetAtt SimpleTodoApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: TodoDataSource
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        export function request(ctx) {
            const { owner, limit, nextToken } = ctx.args;
            const request = {
                operation: "Query",
                query: {
                    expression: "#owner = :owner",
                    expressionNames: { "#owner": "owner" },
                    expressionValues: util.dynamodb.toMapValues({ ":owner": owner }),
                },
                index: "owner-index",
            };
            if (limit !== undefined) request.limit = limit;
            if (nextToken !== undefined) request.nextToken = nextToken;
            return request;
        }
        export function response(ctx) {
            if (ctx.error) {
                util.error(ctx.error.message, ctx.error.type);
            }
            return {
                items: ctx.result.items,
                nextToken: ctx.result.nextToken,
            };
        }
Outputs:
  GraphQLUrl:
    Description: "URL for the GraphQL API"
    Value: !GetAtt SimpleTodoApi.GraphQLUrl
  ApiKey:
    Description: "API Key for simple authentication"
    Value: !GetAtt AppSyncApiKey.ApiKey
  TodoTableName:
    Description: "DynamoDB table name"
    Value: !Ref TodoTable
